+	chunkLimit := initialRangeStreamChunkLimit
+	maxBytes := int64(s.Cfg.MaxRequestBytes)
+	if maxBytes < 1 {
+		maxBytes = 1
+	}
+	remaining := wanted
+	for remaining > 0 {
+		if err := ctx.Err(); err != nil {
+			return err
